Here's a complete, thread-safe LRU cache implementation using a custom doubly linked list and `std::mutex`.

```cpp
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <optional>
#include <stdexcept>

// ─── Node ────────────────────────────────────────────────────────────────────

template <typename Key, typename Value>
struct Node {
    Key   key;
    Value value;
    Node* prev{nullptr};
    Node* next{nullptr};

    Node(Key k, Value v) : key(std::move(k)), value(std::move(v)) {}
};

// ─── Doubly Linked List ───────────────────────────────────────────────────────
// Sentinel head/tail nodes eliminate null checks on insert/remove.

template <typename Key, typename Value>
class DoublyLinkedList {
    using NodeT = Node<Key, Value>;

    NodeT* head;  // sentinel: most-recently used end
    NodeT* tail;  // sentinel: least-recently used end
    size_t sz{0};

public:
    DoublyLinkedList() {
        // Dummy sentinels — never hold real data
        head = new NodeT({}, {});
        tail = new NodeT({}, {});
        head->next = tail;
        tail->prev = head;
    }

    ~DoublyLinkedList() {
        NodeT* cur = head;
        while (cur) {
            NodeT* nxt = cur->next;
            delete cur;
            cur = nxt;
        }
    }

    // No copy — ownership is exclusive
    DoublyLinkedList(const DoublyLinkedList&)            = delete;
    DoublyLinkedList& operator=(const DoublyLinkedList&) = delete;

    size_t size() const { return sz; }

    // Insert node right after head (MRU position)
    void push_front(NodeT* node) {
        node->prev       = head;
        node->next       = head->next;
        head->next->prev = node;
        head->next       = node;
        ++sz;
    }

    // Unlink node without deleting it
    void unlink(NodeT* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        node->prev = node->next = nullptr;
        --sz;
    }

    // Move an already-linked node to the MRU position
    void move_to_front(NodeT* node) {
        unlink(node);
        push_front(node);
    }

    // Remove and return the LRU node (just before tail), or nullptr if empty
    NodeT* pop_back() {
        if (sz == 0) return nullptr;
        NodeT* lru = tail->prev;
        unlink(lru);
        return lru;
    }
};

// ─── LRU Cache ───────────────────────────────────────────────────────────────

template <typename Key, typename Value>
class LRUCache {
    using NodeT = Node<Key, Value>;

    const size_t                          capacity_;
    DoublyLinkedList<Key, Value>          list_;
    std::unordered_map<Key, NodeT*>       map_;
    mutable std::mutex                    mu_;

public:
    explicit LRUCache(size_t capacity) : capacity_(capacity) {
        if (capacity == 0)
            throw std::invalid_argument("LRUCache capacity must be > 0");
        map_.reserve(capacity);
    }

    ~LRUCache() {
        // list_ destructor frees all nodes; map_ just holds raw pointers
    }

    // Returns the value for key, or std::nullopt if not present.
    // Marks the entry as most-recently used.
    std::optional<Value> get(const Key& key) {
        std::lock_guard<std::mutex> lock(mu_);

        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;

        list_.move_to_front(it->second);
        return it->second->value;
    }

    // Insert or update key→value.
    // On insert, evicts the LRU entry if at capacity.
    void put(const Key& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mu_);

        auto it = map_.find(key);
        if (it != map_.end()) {
            // Update existing node in-place
            it->second->value = value;
            list_.move_to_front(it->second);
            return;
        }

        // Evict LRU if full
        if (list_.size() == capacity_) {
            NodeT* lru = list_.pop_back();
            map_.erase(lru->key);
            delete lru;
        }

        // Insert new node
        auto* node = new NodeT(key, value);
        list_.push_front(node);
        map_[key] = node;
    }

    // Convenience helpers
    size_t size()     const { std::lock_guard<std::mutex> lock(mu_); return list_.size(); }
    size_t capacity() const { return capacity_; }  // immutable, no lock needed
};

// ─── Demo ─────────────────────────────────────────────────────────────────────

int main() {
    LRUCache<int, std::string> cache(3);

    cache.put(1, "one");
    cache.put(2, "two");
    cache.put(3, "three");

    // Access key 1 → promotes it to MRU; key 2 becomes LRU
    auto v = cache.get(1);
    std::cout << "get(1): " << v.value_or("miss") << "\n";  // one

    // Inserting key 4 evicts LRU (key 2)
    cache.put(4, "four");

    std::cout << "get(2): " << cache.get(2).value_or("miss") << "\n";  // miss
    std::cout << "get(3): " << cache.get(3).value_or("miss") << "\n";  // three
    std::cout << "get(4): " << cache.get(4).value_or("miss") << "\n";  // four

    // Update existing key
    cache.put(3, "THREE");
    std::cout << "get(3) after update: " << cache.get(3).value_or("miss") << "\n";  // THREE

    std::cout << "size: " << cache.size() << " / " << cache.capacity() << "\n";  // 3 / 3
}
```

**Key design decisions:**

- **Sentinel nodes** — `head` and `tail` are dummy nodes that never hold data. Every real node always has valid `prev`/`next` pointers, so `push_front`, `unlink`, and `pop_back` need no null checks.

- **`unordered_map<Key, Node*>`** — O(1) average lookup. The map owns nothing; the list owns all nodes via raw `new`/`delete`. This avoids `shared_ptr` overhead on every cache hit.

- **Single mutex** — `std::lock_guard` on every public method gives correct mutual exclusion. If you need higher read concurrency, swap it for `std::shared_mutex` with `shared_lock` on `get` and `unique_lock` on `put` — but note that `get` mutates list order, so you'd need to upgrade the lock or accept a different consistency model.

- **`std::optional<Value>` return** — cleaner than sentinel values or exceptions for a cache miss.

- **`move_to_front` on `get`** — a cache hit always promotes the node, maintaining strict LRU ordering.

