```

Here's a clean implementation using preorder traversal with `#` as the null sentinel:

```rust
use std::cell::RefCell;
use std::rc::Rc;

type TreeNode = Rc<RefCell<Node>>;
type OptNode = Option<TreeNode>;

#[derive(Debug)]
struct Node {
    val: i32,
    left: OptNode,
    right: OptNode,
}

impl Node {
    fn new(val: i32) -> TreeNode {
        Rc::new(RefCell::new(Node {
            val,
            left: None,
            right: None,
        }))
    }
}

/// Serializes a binary tree to a comma-separated string.
/// Null nodes are represented by "#".
///
/// Example: Tree [1, 2, 3] -> "1,2,#,#,3,#,#"
fn serialize(root: &OptNode) -> String {
    let mut parts = Vec::new();
    serialize_helper(root, &mut parts);
    parts.join(",")
}

fn serialize_helper(node: &OptNode, parts: &mut Vec<String>) {
    match node {
        None => parts.push("#".to_string()),
        Some(n) => {
            let n = n.borrow();
            parts.push(n.val.to_string());
            serialize_helper(&n.left, parts);
            serialize_helper(&n.right, parts);
        }
    }
}

/// Deserializes a string produced by `serialize` back into a binary tree.
fn deserialize(data: &str) -> OptNode {
    if data.is_empty() {
        return None;
    }
    let mut tokens = data.split(',');
    deserialize_helper(&mut tokens)
}

fn deserialize_helper<'a>(tokens: &mut impl Iterator<Item = &'a str>) -> OptNode {
    match tokens.next() {
        None | Some("#") => None,
        Some(val) => {
            // Safe: serialized data only contains valid i32 values
            let val: i32 = val.parse().expect("invalid token in serialized tree");
            let node = Node::new(val);
            node.borrow_mut().left = deserialize_helper(tokens);
            node.borrow_mut().right = deserialize_helper(tokens);
            Some(node)
        }
    }
}

// --- helpers for testing ---

fn tree_to_vec(root: &OptNode) -> Vec<Option<i32>> {
    let mut result = Vec::new();
    let mut queue = std::collections::VecDeque::new();
    queue.push_back(root.clone());

    while let Some(node) = queue.pop_front() {
        match node {
            None => result.push(None),
            Some(n) => {
                let n = n.borrow();
                result.push(Some(n.val));
                queue.push_back(n.left.clone());
                queue.push_back(n.right.clone());
            }
        }
    }

    // Trim trailing Nones for a cleaner comparison
    while result.last() == Some(&None) {
        result.pop();
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn build_tree() -> OptNode {
        //       1
        //      / \
        //     2   3
        //        / \
        //       4   5
        let root = Node::new(1);
        let left = Node::new(2);
        let right = Node::new(3);
        let rl = Node::new(4);
        let rr = Node::new(5);

        right.borrow_mut().left = Some(rl);
        right.borrow_mut().right = Some(rr);
        root.borrow_mut().left = Some(left);
        root.borrow_mut().right = Some(right);

        Some(root)
    }

    #[test]
    fn test_serialize_format() {
        let tree = build_tree();
        let s = serialize(&tree);
        assert_eq!(s, "1,2,#,#,3,4,#,#,5,#,#");
    }

    #[test]
    fn test_roundtrip() {
        let original = build_tree();
        let serialized = serialize(&original);
        let restored = deserialize(&serialized);

        assert_eq!(tree_to_vec(&original), tree_to_vec(&restored));
    }

    #[test]
    fn test_empty_tree() {
        let s = serialize(&None);
        assert_eq!(s, "#");
        let restored = deserialize(&s);
        assert!(restored.is_none());
    }

    #[test]
    fn test_single_node() {
        let tree = Some(Node::new(42));
        let s = serialize(&tree);
        assert_eq!(s, "42,#,#");
        let restored = deserialize(&s);
        assert_eq!(tree_to_vec(&tree), tree_to_vec(&restored));
    }

    #[test]
    fn test_left_skewed() {
        //   1
        //  /
        // 2
        //  \
        //   3
        let root = Node::new(1);
        let child = Node::new(2);
        let grandchild = Node::new(3);
        child.borrow_mut().right = Some(grandchild);
        root.borrow_mut().left = Some(child);

        let s = serialize(&Some(root.clone()));
        let restored = deserialize(&s);
        assert_eq!(tree_to_vec(&Some(root)), tree_to_vec(&restored));
    }
}
```

Key design decisions:

**Preorder traversal** — visiting root → left → right means the structure is fully encoded without needing to store depth or size metadata. During deserialization, the same traversal order lets you reconstruct the tree by consuming tokens one-by-one recursively.

**`#` sentinel** — null nodes must be explicitly encoded so the deserializer knows when a subtree ends. Without them, `"1,2,3"` is ambiguous between several different tree shapes.

**Shared iterator across recursive calls** — `deserialize_helper` takes `&mut impl Iterator`, so each recursive call advances the same token stream. This is the idiomatic Rust way to avoid index tracking or slicing.

**`Rc<RefCell<Node>>`** — standard interior mutability pattern for tree nodes in Rust when you need shared ownership. If you're building this for a single-threaded context (like LeetCode), this is the right choice. For multi-threaded use, swap to `Arc<Mutex<Node>>`.

