Here's a sliding window rate limiter middleware for Express:

```javascript
// rateLimiter.js
'use strict';

/**
 * Sliding window rate limiter middleware for Express.
 * Tracks request timestamps per IP and evicts entries older than the window.
 *
 * @param {object} options
 * @param {number} options.windowMs   - Window size in milliseconds (default: 1000)
 * @param {number} options.maxRequests - Max requests allowed per window (default: 5)
 */
function createRateLimiter({ windowMs = 1000, maxRequests = 5 } = {}) {
  // Map<ip, number[]> — stores timestamps of recent requests per IP
  const requestLog = new Map();

  // Periodically clean up IPs that have gone quiet to prevent memory leaks.
  // Runs every 10× the window size.
  const cleanupInterval = setInterval(() => {
    const now = Date.now();
    for (const [ip, timestamps] of requestLog.entries()) {
      const active = timestamps.filter((t) => now - t < windowMs);
      if (active.length === 0) {
        requestLog.delete(ip);
      } else {
        requestLog.set(ip, active);
      }
    }
  }, windowMs * 10);

  // Allow the process to exit even if this interval is still running.
  cleanupInterval.unref();

  function rateLimiter(req, res, next) {
    // Prefer the real client IP when behind a trusted proxy.
    // Set `app.set('trust proxy', 1)` in Express if you use a reverse proxy.
    const ip =
      req.ip ||
      req.headers['x-forwarded-for']?.split(',')[0].trim() ||
      req.socket.remoteAddress;

    const now = Date.now();
    const windowStart = now - windowMs;

    // Get existing timestamps for this IP and drop anything outside the window.
    const timestamps = (requestLog.get(ip) ?? []).filter(
      (t) => t > windowStart
    );

    if (timestamps.length >= maxRequests) {
      // Calculate how long until the oldest request falls out of the window.
      const oldestInWindow = timestamps[0]; // array is chronologically ordered
      const retryAfterMs = oldestInWindow + windowMs - now;
      const retryAfterSec = Math.ceil(retryAfterMs / 1000);

      res.set({
        'Retry-After': retryAfterSec,
        'X-RateLimit-Limit': maxRequests,
        'X-RateLimit-Remaining': 0,
        'X-RateLimit-Reset': Math.ceil((oldestInWindow + windowMs) / 1000),
      });

      return res.status(429).json({
        error: 'Too Many Requests',
        message: `Rate limit exceeded. Try again in ${retryAfterSec}s.`,
        retryAfter: retryAfterSec,
      });
    }

    // Record this request and persist the updated log.
    timestamps.push(now);
    requestLog.set(ip, timestamps);

    res.set({
      'X-RateLimit-Limit': maxRequests,
      'X-RateLimit-Remaining': maxRequests - timestamps.length,
      'X-RateLimit-Reset': Math.ceil((windowStart + windowMs) / 1000),
    });

    next();
  }

  // Expose internals for testing and graceful shutdown.
  rateLimiter.resetIp = (ip) => requestLog.delete(ip);
  rateLimiter.destroy = () => clearInterval(cleanupInterval);

  return rateLimiter;
}

module.exports = { createRateLimiter };
```

