'use strict';

const { describe, it, before, after, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const express = require('express');
const { createRateLimiter } = require('./rateLimiter');

function buildApp(options) {
  const app = express();
  const limiter = createRateLimiter(options);
  app.use(limiter);
  app.get('/', (req, res) => res.json({ ok: true }));
  return { app, limiter };
}

// Minimal HTTP helper — avoids pulling in supertest.
function request(app, path = '/') {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, async () => {
      const port = server.address().port;
      try {
        const res = await fetch(`http://127.0.0.1:${port}${path}`);
        const body = await res.json();
        resolve({ status: res.status, headers: res.headers, body });
      } catch (err) {
        reject(err);
      } finally {
        server.close();
      }
    });
  });
}

describe('createRateLimiter', () => {
  it('allows requests under the limit', async () => {
    const { app } = buildApp({ windowMs: 1000, maxRequests: 5 });
    const { status } = await request(app);
    assert.equal(status, 200);
  });

  it('blocks the 6th request within the window', async () => {
    const { app, limiter } = buildApp({ windowMs: 1000, maxRequests: 5 });

    // Simulate 5 prior requests from the same IP by pre-filling the log.
    const now = Date.now();
    limiter._testInject?.('::ffff:127.0.0.1', [now, now, now, now, now]);

    const { status } = await request(app);
    assert.equal(status, 429);
    limiter.destroy();
  });

  it('sets X-RateLimit-Remaining header correctly', async () => {
    const { app, limiter } = buildApp({ windowMs: 1000, maxRequests: 5 });
    const { headers } = await request(app);
    assert.equal(headers.get('x-ratelimit-remaining'), '4');
    limiter.destroy();
  });
});
```

A few things worth noting:

**Why sliding window over fixed window?** Fixed windows can allow burst traffic at window boundaries (up to 2× the limit). The sliding window tracks exact timestamps so the limit is enforced uniformly across any 1-second span.

**Memory management** — the `setInterval` cleanup evicts idle IPs every 10 seconds. For high-traffic production use, swap the in-process `Map` for Redis with a sorted set (ZADD/ZREMRANGEBYSCORE) so the state is shared across multiple Node processes.

**Proxy awareness** — if your app sits behind a load balancer, uncomment `app.set('trust proxy', 1)` so `req.ip` reflects the real client IP rather than the proxy's address. Without it, every request looks like it comes from the same IP and you'll rate-limit yourself.

**Headers** — `Retry-After`, `X-RateLimit-Limit`, `X-RateLimit-Remaining`, and `X-RateLimit-Reset` follow the IETF draft standard, which most HTTP clients and API gateways understand natively.

Here's a fully type-safe `EventEmitter` implementation:

```typescript
// Define the shape of an event map: event name -> payload type
type EventMap = Record<string, unknown>;

// Extract the payload type for a given event key
type EventPayload<TMap extends EventMap, TKey extends keyof TMap> = TMap[TKey];

// Listener function signature
type Listener<TPayload> = (payload: TPayload) => void;

class EventEmitter<TMap extends EventMap> {
  // Store listeners per event key
  private listeners: {
    [TKey in keyof TMap]?: Set<Listener<TMap[TKey]>>;
  } = {};

  /**
   * Register a listener for the given event.
   * Returns an unsubscribe function for convenience.
   */
  on<TKey extends keyof TMap>(
    event: TKey,
    listener: Listener<EventPayload<TMap, TKey>>
  ): () => void {
    if (!this.listeners[event]) {
      this.listeners[event] = new Set();
    }
    this.listeners[event]!.add(listener);

    return () => this.off(event, listener);
  }

  /**
   * Remove a previously registered listener.
   */
  off<TKey extends keyof TMap>(
    event: TKey,
    listener: Listener<EventPayload<TMap, TKey>>
  ): void {
    this.listeners[event]?.delete(listener);
  }

  /**
   * Emit an event, invoking all registered listeners with the payload.
   */
  emit<TKey extends keyof TMap>(
    event: TKey,
    payload: EventPayload<TMap, TKey>
  ): void {
    this.listeners[event]?.forEach((listener) => listener(payload));
  }

  /**
   * Register a one-time listener that removes itself after the first emit.
   */
  once<TKey extends keyof TMap>(
    event: TKey,
    listener: Listener<EventPayload<TMap, TKey>>
  ): () => void {
    const wrapper: Listener<TMap[TKey]> = (payload) => {
      listener(payload);
      this.off(event, wrapper);
    };
    return this.on(event, wrapper);
  }

  /**
   * Remove all listeners for a specific event, or all events if none specified.
   */
  clear<TKey extends keyof TMap>(event?: TKey): void {
    if (event !== undefined) {
      delete this.listeners[event];
    } else {
      this.listeners = {};
    }
  }
}
```

Usage example showing the type safety in action:

```typescript
// 1. Define your event map — event name to payload type
type AppEvents = {
  userLogin:  { userId: string; timestamp: Date };
  userLogout: { userId: string };
  pageView:   { path: string; referrer?: string };
  error:      Error;
};

const emitter = new EventEmitter<AppEvents>();

// ✅ Correct — payload matches the declared type
const unsubscribe = emitter.on("userLogin", ({ userId, timestamp }) => {
  console.log(`User ${userId} logged in at ${timestamp}`);
});

// ✅ once() auto-removes after first emit
emitter.once("error", (err) => {
  console.error("Caught error:", err.message);
});

// ✅ Emit with the correct payload shape
emitter.emit("userLogin", { userId: "u_123", timestamp: new Date() });

// ✅ Unsubscribe via returned function
unsubscribe();

// ✅ Or unsubscribe manually
const handler = (payload: { userId: string }) => console.log(payload.userId);
emitter.on("userLogout", handler);
emitter.off("userLogout", handler);

// ❌ Type error — 'email' is not a key of AppEvents
// emitter.on("email", () => {});

// ❌ Type error — payload is missing 'timestamp'
// emitter.emit("userLogin", { userId: "u_123" });

// ❌ Type error — wrong payload type for this event
// emitter.emit("error", { message: "oops" }); // must be an Error instance
```

A few design notes worth calling out:

- The mapped type `{ [TKey in keyof TMap]?: Set<Listener<TMap[TKey]>> }` keeps each event's listener set typed to its own payload, so there's no `any` or casting internally.
- `on` returns an unsubscribe function — a common pattern that avoids having to hold a reference to the listener just to call `off`.
- `once` wraps the listener in a self-removing closure rather than adding special-case logic to `emit`, keeping the hot path clean.
- Using `Set` instead of an array prevents accidental duplicate registrations of the same listener reference.

